/** The whole export, Android style, 24 hour clock, day first. */
export const bilingualChat: string = MESSAGES.map(([monthDay, who, time, text]) => {
  const [month, day] = monthDay.split('-');
  return `${day}/${month}/2024, ${time} - ${NAME[who]}: ${text}`;
}).join('\n');

